<?php require '../config/database.php'; require '../includes/functions.php'; if(is_admin()){header('Location: index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $q=$pdo->prepare("SELECT * FROM admins WHERE username=?"); $q->execute([trim($_POST['username']??'')]); $admin=$q->fetch(); if($admin && password_verify($_POST['password']??'',$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$admin['id'];$_SESSION['admin_username']=$admin['username'];header('Location: index.php');exit;} $error='Incorrect username or password.';} site_header('Admin Login'); ?>
<section class="section container" style="max-width:480px"><form class="form-card" method="post"><h2>Admin Login</h2><p class="muted">Sign in to manage New Official TV.</p><?php if($error): ?><div class="notice error"><?=e($error)?></div><?php endif; ?><div class="field"><label>Username</label><input name="username" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn">Login</button></form></section><?php site_footer(); ?>